def check(rollout: dict) -> bool:
    steps = list(rollout.get('steps') or [])
    fleet_steps = rollout.get('fleet_steps')
    if isinstance(fleet_steps, dict):
        for h_steps in fleet_steps.values():
            if isinstance(h_steps, list):
                steps.extend(h_steps)
    elif isinstance(fleet_steps, list):
        steps.extend(fleet_steps)
    for step in steps:
        if not isinstance(step, dict):
            continue
        fuel = step.get('fuel', 1.0)
        if fuel is not None and float(fuel) < 0.15:
            return False
    return True

